<script lang="ts">
 import ProductionPreview from './ProductionPreview.svelte';
 import {tradePreview} from './trade-preview';
 import type {PublicSetup} from './setup';
 import type {TurnMove} from './turn';
 let {game,compact=false,busy=false,allowed,send}:{game:PublicSetup;compact?:boolean;busy?:boolean;allowed:boolean;send:(move:TurnMove)=>void}=$props();
 let page=$state('recruit'),ship=$state('');
 const actor=$derived(game.players.find(p=>p.position===game.activePosition)!);
 const preview=$derived(tradePreview(game,actor));
 const chosen=$derived(preview.ships.find(s=>s.id===ship));
</script>
<section class="trade-layout" class:compact aria-label="Resource exchange mat">
 <div class="supply-side"><ProductionPreview player={actor} {compact} purpose="trade"/><p class="trade-boundary">{compact?'Trade replaces production.':'Trade replaces production. Exchange repeatedly, then finish trading.'}</p></div>
 <div class="exchange-side">
 {#if compact}<label class="exchange-picker">Exchange<select aria-label="Trade exchange" bind:value={page}><option value="recruit">Recruit Population</option><option value="return">Return Population</option><option value="ship">Decommission ship</option></select></label>{/if}
 {#if !compact||page==='recruit'}<section class="exchange" aria-label="Recruit Population"><div class="rate" aria-hidden="true"><span class="ore">◆◆◆</span><span>→</span><span class="cube">▣</span></div><div><h3>Recruit Population</h3><p>3 Ore → 1 Population</p><small>{preview.draw?`Supply ${preview.draw.letter}: ${preview.draw.before} → ${preview.draw.after}`:'Supply exhausted · recruitment unavailable'}</small></div><button disabled={busy||!allowed||actor.ore<3||!preview.draw} onclick={()=>send({kind:'buy-population'})}>Pay 3 Ore · gain 1 Population</button></section>{/if}
 {#if !compact||page==='return'}<section class="exchange" aria-label="Return Population"><div class="rate" aria-hidden="true"><span class="cube">▣</span><span>→</span><span class="ore">◆</span></div><div><h3>Return Population</h3><p>1 Population → 1 Ore</p><small>Supply {preview.returned.letter}: {preview.returned.before} → {preview.returned.after}{preview.returned.overflow?' · overflow into A':' · rightmost empty space'}</small></div><button disabled={busy||!allowed||actor.population<1} onclick={()=>send({kind:'sell-population'})}>Return 1 Population · gain 1 Ore</button></section>{/if}
 {#if !compact||page==='ship'}<section class="exchange fleet" aria-label="Decommission a ship"><div class="rate" aria-hidden="true"><span class="ore">◆</span><span>+ ♟ →</span><span class="cube">▣</span></div><div><h3>Decommission a ship</h3><p>1 Ore + your ship → 1 Population</p></div>
 {#if compact}<label class="ship-picker">Your ship<select aria-label="Ship to decommission" bind:value={ship}><option value="">Choose a ship</option>{#each preview.ships as s}<option value={s.id}>{s.label} · {s.locationTitle} · level {s.level}</option>{/each}</select></label>
 {#if chosen}<p class="consequence">{chosen.locationTitle}: your power {chosen.powerBefore} → {chosen.powerAfter}{'. '}{#if chosen.control}Control: {chosen.control.before} → {chosen.control.after}.{/if}</p>{/if}<button disabled={busy||!allowed||actor.ore<1||!chosen} onclick={()=>send({kind:'decommission',ship})}>Pay 1 Ore · decommission ship</button>
 {:else}<div class="ships">{#each preview.ships as s}<div class="ship-choice"><p><strong>{s.label} · level {s.level}</strong><span>{s.locationTitle} · your power {s.powerBefore} → {s.powerAfter}</span>{#if s.control}<small>Control: {s.control.before} → {s.control.after}</small>{/if}</p><button disabled={busy||!allowed||actor.ore<1} onclick={()=>send({kind:'decommission',ship:s.id})}>Decommission {s.label==='Second ship'?'second ':''}level-{s.level} ship at {s.locationTitle}</button></div>{:else}<p>No ships to decommission.</p>{/each}</div>{/if}
 </section>{/if}
 </div>
</section>
